CREATE TABLE adjustment_factors(symbol VARCHAR, ex_date DATE, factor_price DOUBLE NOT NULL, factor_volume DOUBLE NOT NULL, PRIMARY KEY(symbol, ex_date));;
CREATE TABLE candles_1d_raw(symbol VARCHAR NOT NULL, date DATE NOT NULL, open DOUBLE NOT NULL, high DOUBLE NOT NULL, low DOUBLE NOT NULL, "close" DOUBLE NOT NULL, volume BIGINT NOT NULL);;
CREATE TABLE candles_1m_raw(symbol VARCHAR NOT NULL, "timestamp" TIMESTAMP NOT NULL, open DOUBLE NOT NULL, high DOUBLE NOT NULL, low DOUBLE NOT NULL, "close" DOUBLE NOT NULL, volume BIGINT NOT NULL);;
CREATE TABLE corporate_actions(id VARCHAR PRIMARY KEY, symbol VARCHAR NOT NULL, action_type VARCHAR NOT NULL, ex_date DATE NOT NULL, record_date DATE, ratio_from DOUBLE, ratio_to DOUBLE, dividend_amount DOUBLE, description VARCHAR, created_at TIMESTAMP DEFAULT(CURRENT_TIMESTAMP));;
CREATE TABLE download_checkpoints(symbol VARCHAR, timeframe VARCHAR, earliest_ts TIMESTAMP, latest_ts TIMESTAMP, total_candles INTEGER DEFAULT(0), status VARCHAR DEFAULT('PENDING'), consecutive_empty_count INTEGER DEFAULT(0), last_attempt_at TIMESTAMP, error_message VARCHAR, PRIMARY KEY(symbol, timeframe));;
CREATE TABLE job_logs(job_id VARCHAR PRIMARY KEY, job_type VARCHAR NOT NULL, started_at TIMESTAMP NOT NULL, completed_at TIMESTAMP, symbols_processed INTEGER DEFAULT(0), symbols_failed INTEGER DEFAULT(0), total_candles_ingested BIGINT DEFAULT(0), status VARCHAR NOT NULL, details VARCHAR);;
CREATE TABLE market_holidays(holiday_date DATE PRIMARY KEY, description VARCHAR NOT NULL, is_special_session BOOLEAN DEFAULT(CAST('f' AS BOOLEAN)), trading_start TIME DEFAULT('09:15:00'), trading_end TIME DEFAULT('15:30:00'));;
CREATE TABLE schema_version("version" VARCHAR PRIMARY KEY, applied_at TIMESTAMP DEFAULT(CURRENT_TIMESTAMP), description VARCHAR NOT NULL);;
CREATE TABLE symbols(symbol VARCHAR PRIMARY KEY, "name" VARCHAR NOT NULL, isin VARCHAR, exchange VARCHAR DEFAULT('NSE'), segment VARCHAR DEFAULT('EQUITY'), series VARCHAR DEFAULT('EQ'), lot_size INTEGER DEFAULT(1), tick_size DOUBLE DEFAULT(0.05), category VARCHAR, tier INTEGER DEFAULT(4) NOT NULL, priority_rank INTEGER DEFAULT(9999), listing_date DATE, is_active BOOLEAN DEFAULT(CAST('t' AS BOOLEAN)), updated_at TIMESTAMP DEFAULT(CURRENT_TIMESTAMP));;
CREATE VIEW candles_1d_adjusted AS SELECT c.symbol, c.date, (c.open * COALESCE(af.factor_price, 1.0)) AS open, (c.high * COALESCE(af.factor_price, 1.0)) AS high, (c.low * COALESCE(af.factor_price, 1.0)) AS low, (c."close" * COALESCE(af.factor_price, 1.0)) AS "close", CAST((c.volume * COALESCE(af.factor_volume, 1.0)) AS BIGINT) AS volume FROM candles_1d_raw AS c LEFT JOIN adjustment_factors AS af ON (((c.symbol = af.symbol) AND (c.date <= af.ex_date)));;
CREATE VIEW candles_1m_adjusted AS SELECT c.symbol, c."timestamp", (c.open * COALESCE(af.factor_price, 1.0)) AS open, (c.high * COALESCE(af.factor_price, 1.0)) AS high, (c.low * COALESCE(af.factor_price, 1.0)) AS low, (c."close" * COALESCE(af.factor_price, 1.0)) AS "close", CAST((c.volume * COALESCE(af.factor_volume, 1.0)) AS BIGINT) AS volume FROM candles_1m_raw AS c LEFT JOIN adjustment_factors AS af ON (((c.symbol = af.symbol) AND (CAST(c."timestamp" AS DATE) <= af.ex_date)));;

